<?php require '../../../config/bootstrap.php';rate_limit('iot_result',120,60);$key=$_SERVER['HTTP_X_DEVICE_KEY']??'';$d=request_json();$code=trim((string)($d['device_code']??''));$hash=hash_hmac('sha256',$key,envv('DEVICE_KEY_PEPPER','change-me'));$s=db()->prepare('SELECT d.*,c.secret_hash FROM devices d JOIN device_credentials c ON c.device_id=d.id AND c.active=1 WHERE d.device_code=? LIMIT 1');$s->execute([$code]);$dev=$s->fetch();if(!$dev||!hash_equals($dev['secret_hash'],$hash))json_response(['error'=>'Não autorizado'],401);$status=$d['status']??'failed';if(!in_array($status,['executed','failed'],true))json_response(['error'=>'Estado inválido'],422);$s=db()->prepare('UPDATE device_commands SET status=?,result_message=?,completed_at=NOW() WHERE id=? AND device_id=? AND status IN ("sent","queued")');$s->execute([$status,(string)($d['message']??''),(int)($d['command_id']??0),$dev['id']]);db()->prepare('UPDATE devices SET last_seen_at=NOW() WHERE id=?')->execute([$dev['id']]);json_response(['ok'=>true]);
